	["Otros addons (%d): %s"] = "Другие аддоны (%d): %s",
	["Otros addons pueden poner puntos de ruta"] = "Разрешить другим аддонам ставить путевые точки",
	["Otros caminos"] = "Другие пути",
	["Otros jugadores"] = "Другие игроки",
	["Oye, ¿a la tuya también le gustan las salchichas?"] = "Слушай, а твоя тоже любит сосиски?",
	["PNJ"] = "NPC",
	["PNJ %d"] = "NPC %d",
	["Paciencia de lobo"] = "Волчье терпение",
	["Paciencia: lo que se busca con calma, se encuentra."] = "Терпение: что ищешь спокойно, то и находишь.",
	["Paisaje"] = "Пейзаж",
