	["Usar un perfil"] = "Использовать профиль",
	["Usar una venda"] = "Использовать бинт",
	["Usarlo"] = "Использовать",
	["Usas el perfil «%s»"] = "Используется профиль «%s»",
	["Usas las bolsas del juego"] = "Вы используете сумки игры",
	["Uso: /alfa comercio precio <enlace del objeto>"] = "Использование: /alfa comercio precio <ссылка на предмет>",
	["Uso: /alfa comercio precio <objeto o su nombre>"] = "Использование: /alfa comercio precio <предмет или его название>",
	["Uso: /alfa recoleccion [ruta [mineria|hierbas|pesca|tesoros] | guiar | parar | mapa | minimapa]"] = "Использование: /alfa recoleccion [ruta [mineria|hierbas|pesca|tesoros] | guiar | parar | mapa | minimapa]",
	["Uso: /alfa recoleccion [ruta [mineria|hierbas|pesca|tesoros] | subir [mineria|hierbas] | guiar | parar | mapa | minimapa]"] = "Команда: /alfa recoleccion [ruta [mineria|hierbas|pesca|tesoros] | subir [mineria|hierbas] | guiar | parar | mapa | minimapa]",
	["Uso: /alfa silenciar <número>, /alfa silenciar quitar <número>, /alfa silenciar borrar."] = "Использование: /alfa silenciar <номер>, /alfa silenciar quitar <номер>, /alfa silenciar borrar.",
	["Va %d"] = "Идёт %d",
	["Va a %s"] = "Идет в %s",
	["Vaciar"] = "Очистить",
	["Vaciar la lista"] = "Очистить список",
	["Vacía"] = "Пусто",
	["Vaelastrasz, un dragón rojo, está preso de Nefarian en la Guarida Alanegra. Antes de pelear contra ti, te presta su fuerza."] = "Вейластраз, красный дракон, — пленник Нефариана в Логове Крыла Тьмы. Перед боем с тобой он одалживает тебе свою силу.",
	["Vale"] = "Стоит",
	["Vale la pena: abre “%s”"] = "Стоит того: открывает «%s»",
	["Vale la pena: da %s"] = "Стоит того: дает %s",
	["Vallefresno es un bosque precioso. Pero cuida de no enojar a sus espíritus antiguos."] = "Ясеневый лес прекрасен. Но старайся не гневить его древних духов.",
	["Valor de %s: llevas %s"] = "Стоимость %s: уже %s",
	["Valor de bloqueo"] = "Показатель блока",
	["Valor de lo pescado"] = "Стоимость улова",
	["Valor de venta"] = "Цена у торговца",
	["Valor en la subasta"] = "Цена на аукционе",
	["Valor exacto"] = "Точное значение",
	["Vamos a %s: %s. Sigue la flecha."] = "Идём к %s: %s. Следуй за стрелкой.",
	["Vamos a %s: sigue la flecha."] = "Идем в %s: следуй за стрелкой.",
	["Vamos a entregar %s con %s: sigue la flecha."] = "Сдаём «%s» персонажу %s: следуй за стрелкой.",
	["Vamos a una zona de tu nivel: %s."] = "Идём в зону твоего уровня: %s.",
	["Vamos con %s a tomar %s."] = "Идём к %s за заданием %s.",
	["Vamos con %s: ahí empieza “%s”."] = "Идём к %s: там начинается «%s».",
	["Van %d"] = "Идут: %d",
	["Van %d intentos. Respiren, esperen a que todos tengan maná y vuelvan."] = "Уже %d попыток. Выдохните, дождитесь маны у всех и снова в бой.",
	["Van: %s"] = "Идут: %s",
	["Van: %s."] = "Идут: %s.",
	["Variable del juego: %s"] = "Переменная игры: %s",
	["Varimathras sirve a Sylvanas en Entrañas. Es un señor del terror, así que nadie sabe cuánto le va a durar la lealtad."] = "Вариматрас служит Сильване в Подгороде. Он повелитель ужаса, так что никто не знает, надолго ли хватит его верности.",
	["Varios"] = "Разное",
	["Varios enemigos cerca: Nova sagrada los golpea a todos."] = "Рядом несколько противников: Кольцо света бьет их всех.",
	["Varios enemigos cerca: el cono los golpea y los frena."] = "Рядом несколько противников: конус бьет и замедляет их.",
	["Varios enemigos cerca: el tótem de magma los quema a todos."] = "Рядом несколько противников: Тотем магмы сжигает их всех.",
	["Varios enemigos cerca: golpéalos a todos a la vez."] = "Рядом несколько противников: бейте всех сразу.",
	["Varios enemigos cerca: la ola los golpea y los frena."] = "Рядом несколько противников: волна бьет и замедляет их.",
	["Varios enemigos juntos: el huracán los golpea a todos."] = "Несколько противников вместе: Гроза бьет их всех.",
	["Varios enemigos juntos: la ventisca los golpea a todos."] = "Несколько противников вместе: Снежная буря бьет их всех.",
	["Varios enemigos juntos: lluvia de fuego sobre ellos."] = "Несколько противников вместе: обрушьте на них Огненный ливень.",
	["Varios enemigos juntos: quémalos a todos a la vez."] = "Несколько противников вместе: сожгите их всех разом.",
	["Varios enemigos: consagra el suelo bajo ti."] = "Несколько противников: освятите землю под собой.",
	["Varios enemigos: el disparo alcanza a varios."] = "Несколько противников: выстрел задевает нескольких.",
	["Varios enemigos: el rayo salta entre ellos."] = "Несколько противников: молния перескакивает между ними.",
	["Varios enemigos: golpéalos a todos."] = "Несколько противников: бейте всех.",
	["Varios enemigos: tus golpes alcanzan a otro más."] = "Несколько противников: ваши удары задевают еще одного.",
	["Varios misiles que no fallan. Bueno cuando el enemigo no se mueve."] = "Несколько снарядов, которые никогда не промахиваются. Хорошо, когда враг стоит на месте.",
	["Varios puntos juntos: acércate en el mapa para verlos."] = "Несколько точек рядом: приблизьте карту, чтобы их увидеть.",
	["Varita"] = "Жезл",
	["Vas"] = "Ты идёшь",
	["Vas camino al primer jefe."] = "Вы на пути к первому боссу.",
	["Vas con tu grupo"] = "Вы в группе",
	["Vas en %d de %d"] = "Пройдено: %d из %d",
	["Vas entre el jefe %d y el %d (%d de %d vencidos)."] = "Вы между боссом %d и боссом %d (побеждено %d из %d).",
	["Vas muy bien. Cada paso cuenta, aunque no lo parezca."] = "У тебя отлично получается. Каждый шаг важен, даже если так не кажется.",
	["Vas solo"] = "Вы один",
	["Vas tras %s"] = "Вы идете за: %s",
	["Ve a la torre"] = "Иди к башне",
	["Ve al andén"] = "Иди на платформу",
	["Ve al elevador"] = "Иди к лифту",
	["Ve al muelle"] = "Иди на причал",
	["Ve al portal"] = "Иди к порталу",
	["Ve con cuidado: la presa también muerde."] = "Осторожнее: добыча тоже кусается.",
	["Ve con el maestro de vuelo"] = "Иди к распорядителю полётов",
	["Ve quién de tu hermandad busca grupo y pon tu anuncio. Se quita solo en una hora."] = "Смотри, кто из гильдии ищет группу, и размещай свое объявление. Само исчезнет через час.",
	["Veces completada"] = "Сколько раз пройдено",
	["Veces completadas"] = "Число прохождений",
	["Veces que te levantaste"] = "Сколько раз ты поднимался",
	["Vegetación"] = "Растительность",
	["Veinte. Ya te respetan en los caminos."] = "Двадцать. На дорогах тебя уже уважают.",
	["Vela sagrada"] = "Святая свеча",
	["Velen, Kil'jaeden y Archimonde guiaban a los eredar. Los dos últimos aceptaron el poder de Sargeras; Velen huyó."] = "Велен, Кил'джеден и Архимонд вели эредаров. Двое последних приняли силу Саргераса; Велен бежал.",
	["Velocidad"] = "Скорость",
	["Velocidad del zoom"] = "Скорость приближения",
	["Ven a jugar con la manada, pregunta lo que quieras o cuéntanos si algo falla. Haz clic en el cuadro y cópialo con Ctrl+C (Cmd+C en Mac)."] = "Приходи играть со стаей, спрашивай что угодно или расскажи, если что-то сломалось. Щелкни по полю и скопируй через Ctrl+C (Cmd+C на Mac).",
	["Vence a este jefe para descubrir su nombre y su botín."] = "Победите этого босса, чтобы узнать его имя и добычу.",
	["Vence a sus jefes para ver lo que sueltan, o apaga el modo historia en Ajustes."] = "Победите боссов, чтобы увидеть, что с них падает, или выключите режим истории в «Настройках».",
	["Vence a sus jefes para ver lo que sueltan, o apaga el modo historia."] = "Победите боссов, чтобы увидеть, что с них падает, или выключите режим истории.",
	["Vencido"] = "Побежден",
	["Venció"] = "Истёк",
	["Vendas para curarte sin gastar maná ni esperar: imprescindible para todos."] = "Бинты, чтобы лечиться без маны и ожидания: обязательно для всех.",
