	["~%d misiones"] = "~%d заданий",
	["~%d misión"] = "~%d задание",
	["¡%d mazmorras esta semana! Y volviste para contarlo."] = "%d подземелий за неделю! И ты вернулся, чтобы рассказать.",
	["¡%d misiones en una semana! Eso ya es de leyenda."] = "%d заданий за неделю! Это уже легенда.",
	["¡%d misiones entregadas hoy! Así se caza en manada."] = "Сегодня сдано заданий: %d! Вот так охотится стая.",
	["¡%d misiones esta semana! La manada aúlla por ti."] = "%d заданий за неделю! Стая воет в твою честь.",
	["¡%d misiones hoy! A este paso me debes una salchicha."] = "Заданий сегодня: %d! Так ты мне скоро сосиску будешь должен.",
	["¡%d misiones hoy! Estás que no te para nadie."] = "Сегодня заданий: %d! Тебя не остановить.",
	["¡%d peces en una semana! El lago ya te conoce."] = "%d рыб за неделю! Озеро тебя уже знает.",
	["¡%d peces esta semana! Me guardas uno, ¿verdad?"] = "%d рыб за неделю! Оставишь мне одну, правда?",
	["¡%d veces ayudaste a la manada esta semana! Eres de los que hacen manada."] = "Ты помог стае %d раз за неделю! Ты из тех, на ком держится стая.",
	["¡%s %d!"] = "%s %d!",
	["¡%s al máximo: %d/%d! Ya no hay nada que te enseñen. Qué orgullo, de verdad."] = "%s на максимуме: %d/%d! Учить тебя больше нечему. Как же я горжусь, правда.",
	["¡%s cazó a %s!"] = "%s добыл: %s!",
	["¡%s días juntos!"] = "%s дней вместе!",
	["¡%s es tu aprendiz!"] = "%s — твой ученик!",
	["¡%s llegó a la manada con Alfa!"] = "%s пришёл в стаю с Alfa!",
	["¡%s llegó al nivel %d!"] = "%s достиг %d-го уровня!",
	["¡%s subió a nivel %d! Auuuu, felicidades."] = "%s получил уровень %d! Ауууу, поздравляю.",
	["¡%s tiene su primera montura!"] = "%s получил первого скакуна!",
	["¡%s ya está feliz! Así sí da gusto cazar juntos."] = "%s уже доволен! Вот так охотиться вместе — одно удовольствие.",
	["¡%s!"] = "%s!",
	["¡%s! Hace días que no te veía. En Hoy te digo dónde íbamos."] = "%s! Давно тебя не видела. На странице «Сегодня» я покажу, где мы остановились.",
	["¡%s! Llegué despacito, que ya es de noche. Te extrañé."] = "%s! Я пришла тихонько, ведь уже ночь. Я скучала.",
	["¡%s! Si algo te pega, corre hacia el tanque, no lejos de él."] = "%s! Если тебя бьют, беги к танку, а не от него.",
	["¡%s! Te extrañé mucho. Vine corriendo en cuanto te vi llegar."] = "%s! Я так по тебе скучала. Прибежала, как только тебя увидела.",
	["¡%s, listo! La manada aúlla por ti. Auuuu. ¿Y mi salchicha?"] = "%s, готово! Стая воет в твою честь. Ау-у-у. А моя сосиска?",
	["¡%s, volviste! Te extrañé tanto que no paraba de mover la cola."] = "%s, ты снова здесь! Я так скучала, что всё время виляла хвостом.",
	["¡A cazar!"] = "На охоту!",
	["¡A jalar!"] = "Пулим!",
	["¡Abrumar!"] = "Превосходство!",
	["¡Ahora sí te sigo corriendo con la lengua de fuera!"] = "Теперь я бегу за тобой, высунув язык!",
	["¡Ahora!"] = "Сейчас!",
	["¡Ahí estás, %s! Si quieres un consejo, dame clic."] = "Вот ты где, %s! Если нужен совет, щелкни по мне.",
	["¡Ahí estás, %s! Te estaba esperando… te extrañé."] = "Вот и ты, %s! Я тебя ждала… я скучала.",
	["¡Al máximo!"] = "Максимум!",
	["¡Arriba, lobo! Antes de volver a pelear, recupera vida y maná."] = "Подъем, волк! Перед новым боем восстанови здоровье и ману.",
	["¡Arriba, lobo! Caer es parte de la cacería. Al revivir, repara tu equipo."] = "Подъем, волк! Падать — часть охоты. Когда воскреснешь, почини экипировку.",
	["¡Arriba, lobo! Libera tu espíritu: la flecha te dice si conviene tu cuerpo o el sanador."] = "Подъем, волк! Освободи дух: стрелка подскажет, что лучше — тело или целитель душ.",
	["¡Arriba, lobo! Si eran muchos, la próxima jálalos de uno en uno."] = "Подъем, волк! Если их было много, в следующий раз выманивай по одному.",
	["¡Arriba, nivel %d! Si tienes un punto de talento libre, no lo olvides."] = "Выше, уровень %d! Если есть свободное очко талантов, не забудь о нем.",
	["¡Así se ve un aviso!"] = "Так выглядит оповещение!",
	["¡Ataque de la victoria!"] = "Победный раж!",
	["¡Auuu!"] = "Ауууу!",
	["¡Auuu! Juntas cazamos mejor."] = "Ау-у! Вместе мы охотимся лучше.",
	["¡Auuu! Registro limpio: %s. Eso merece una salchicha."] = "Ауууу! Журнал чист: %s. Это заслуживает сосиску.",
	["¡Auuu! Toda la manada está de fiesta."] = "Ауууу! Вся стая празднует.",
	["¡Auuuu! La manada unida no se rinde."] = "Ау-у-у! Сплоченная стая не сдается.",
	["¡Auuuu! ¡Nivel %d y dos niveles en menos de media hora! Vas como lobo en luna llena."] = "Ауууу! Уровень %d, и два уровня меньше чем за полчаса! Ты как волк в полнолуние.",
	["¡Bien hecho! %s"] = "Отлично! %s",
	["¡Bienvenido a %s!"] = "Добро пожаловать в %s!",
	["¡Bienvenido a la manada! Si necesitas algo, aquí estamos. ¡Auuu!"] = "Добро пожаловать в стаю! Если что-то нужно — мы рядом. Ауууу!",
	["¡Buen día, %s! El sol ya salió en Azeroth. ¿Vamos?"] = "Доброе утро, %s! Солнце уже встало над Азеротом. Идём?",
	["¡Buen día, %s! Te extrañé toda la noche. ¿A dónde vamos hoy?"] = "Добрый день, %s! Я скучала всю ночь. Куда сегодня?",
	["¡Buenas noches, %s!"] = "Добрый вечер, %s!",
	["¡Buenas noches, %s! Las lobas cazamos mejor de noche."] = "Добрый вечер, %s! Мы, волчицы, лучше всего охотимся ночью.",
	["¡Buenas tardes, %s!"] = "Добрый день, %s!",
	["¡Buenas tardes, %s! Buena hora para unas misiones."] = "Добрый день, %s! Отличное время для заданий.",
	["¡Buenas, %s! Paso a paso se llega lejos."] = "Привет, %s! Шаг за шагом можно уйти далеко.",
	["¡Buenos días! Un buen desayuno y a cazar, que la mañana rinde."] = "Доброе утро! Хороший завтрак — и на охоту: утром успеваешь многое.",
	["¡Buenos días, %s!"] = "Доброе утро, %s!",
	["¡Buenos días, %s! Me estiro, bostezo y estoy lista."] = "Доброе утро, %s! Потянусь, зевну — и я готова.",
	["¡Buenos días, %s! Vine corriendo con el sol. ¿Desayunamos aventura?"] = "Доброе утро, %s! Я прибежала вместе с солнцем. Приключение на завтрак?",
	["¡Bájale, casi se lo quitas al tanque!"] = "Сбавь, ты вот-вот сорвешь его с танка!",
	["¡Cerraste tu ruta!"] = "Маршрут пройден!",
	["¡Cien días de caza juntos! Eres de los que no se rinden."] = "Сто дней охоты вместе! Ты из тех, кто не сдаётся.",
	["¡Cien días desde que empezamos! Mira todo lo que hemos hecho: está en «Tu temporada»."] = "Сто дней с тех пор, как мы начали! Посмотри, сколько мы сделали: всё в «Твоём сезоне».",
	["¡Cincuenta días de caza! Ya conozco tu paso de memoria."] = "Пятьдесят дней охоты! Я уже знаю твой шаг наизусть.",
	["¡Claro! Saludo a tu mascota cuando la llamas y, si eres cazador, te aviso cuando tiene hambre o está triste para que le des de comer."] = "Конечно! Я здороваюсь с твоим питомцем, когда ты его зовешь, и, если ты охотник, говорю, когда он голоден или несчастен, чтобы ты его покормил.",
	["¡Completaste %s!"] = "Пройдено: %s!",
	["¡Con esta subes de nivel!"] = "С этим ты получишь уровень!",
	["¡Contraataque!"] = "Контратака!",
	["¡Cumplido!"] = "Готово!",
	["¡Cumplido! Salchicha ganada."] = "Выполнено! Сосиска заработана.",
	["¡Córtale a tu foco!"] = "Прерви фокус!",
	["¡Córtalo!"] = "Прерви!",
	["¡De vuelta con la manada!"] = "Снова со стаей!",
	["¡De vuelta en la manada, %s!"] = "Снова в стае, %s!",
	["¡De vuelta! Te cuento todo otra vez."] = "Я снова здесь! Буду рассказывать обо всём.",
	["¡Descubriste un lugar nuevo!"] = "Вы открыли новое место!",
	["¡Ejecutar!"] = "Казнь!",
	["¡El barco ya está aquí!"] = "Корабль уже здесь!",
	["¡El barco ya está en el muelle! Sale en %s"] = "Корабль уже у причала! Отходит через %s",
	["¡El elevador ya está aquí!"] = "Лифт уже здесь!",
	["¡El elevador ya está aquí! Sale en %s"] = "Лифт уже здесь! Отправится через %s",
	["¡El tranvía ya está aquí!"] = "Поезд уже здесь!",
	["¡El tranvía ya está en el andén! Sale en %s"] = "Трамвай уже на платформе! Отходит через %s",
	["¡El zepelín ya está aquí!"] = "Дирижабль уже здесь!",
	["¡El zepelín ya está en la torre! Sale en %s"] = "Дирижабль уже у башни! Отлетает через %s",
	["¡En Thelsamar venden morcilla! La morcilla de Thelsamar es casi una salchicha... ¿me compras una?"] = "В Телсамаре продают кровяную колбасу! Телсамарская кровяная колбаса — почти сосиска... купишь мне одну?",
	["¡Es Halloween de Azeroth! Pide dulces a los posaderos: a veces te disfrazan de algo chistoso."] = "Тыквовин! Попроси у трактирщиков угощение: иногда они наряжают тебя во что-нибудь смешное.",
	["¡Es ahora! Hasta las %s"] = "Уже идет! До %s",
	["¡Es el Festival del Fuego del Solsticio! Visita las hogueras de las ciudades y honra su llama."] = "Огненный солнцеворот! Посети костры городов и почти их пламя.",
	["¡Espera! Dejas %d misiones listas sin entregar. Si no, mañana empezamos por ahí."] = "Подожди! Готовых заданий без сдачи: %d. Если не сейчас, в следующий раз начнем с них.",
	["¡Este objeto tiene candado!"] = "Этот предмет под замком!",
	["¡Esto le sirve a %s!"] = "Это пригодится: %s!",
	["¡Está lanzando!"] = "Он произносит заклинание!",
	["¡Explorada completa!"] = "Исследовано полностью!",
	["¡Felicidades por el nivel %d, %s! Auuuu."] = "Поздравляю с уровнем %d, %s! Ауууу.",
	["¡Feliz cumpleaños!"] = "С днем рождения!",
	["¡Feliz cumpleaños, Alfa!"] = "С днем рождения, Alfa!",
	["¡Gracias por probar Alfa!"] = "Спасибо, что тестируешь Alfa!",
	["¡Gracias! Se enviará solo la próxima vez que abras el instalador de Alfa. Si lo quieres mandar ya: «Enviar ya por el navegador»."] = "Спасибо! Он отправится сам, когда ты в следующий раз откроешь установщик Alfa. Чтобы отправить сразу: «Отправить через браузер».",
	["¡Gracias! Ya van %d salchichas que me das. Las llevo contadas, eh."] = "Спасибо! Сосисок от тебя уже: %d. Я их считаю, между прочим.",
	["¡Hasta pronto! Aquí te espero, cuidando tu lugar."] = "До скорого! Я жду тебя здесь и стерегу твое место.",
	["¡Hasta pronto! Hoy cazamos %s Aquí te espero."] = "До скорого! Сегодня мы добыли: %s Я жду тебя здесь.",
	["¡Hay algo nuevo en Alfa: %s! ¿Te lo enseño?"] = "В Alfa есть новое: %s! Показать?",
	["¡Hola!"] = "Привет!",
	["¡Hola! Empecemos"] = "Привет! Начнём",
	["¡Hola! Pregúntame lo que quieras de Alfa: te lo explico corto y te llevo."] = "Привет! Спрашивай что угодно об Alfa: объясню коротко и отведу.",
	["¡Hola! Soy Lya, la loba de confianza del Alfa. Cuido a la manada y voy contigo en el camino."] = "Привет! Я Lya, верная волчица Альфы. Я берегу стаю и иду с тобой в пути.",
	["¡Hola! Soy Lya, la loba de confianza del Alfa. Voy a acompañarte en esta configuración y después en tu camino."] = "Привет! Я Лия, верная волчица Альфы. Я проведу тебя через настройку, а потом буду рядом в пути.",
	["¡Hola, %s!"] = "Привет, %s!",
	["¡Hola, %s! Familia %s y de buena casta. Tú y yo vamos a cuidar a nuestro alfa."] = "Привет, %s! Семейство %s, и хорошей породы. Мы с тобой будем беречь нашего альфу.",
	["¡Hola, %s! Hoy huele a buena cacería."] = "Привет, %s! Сегодня пахнет хорошей охотой.",
	["¡Hola, %s! La tarde pinta tranquila. ¿Qué cazamos hoy?"] = "Привет, %s! День обещает быть спокойным. На кого охотимся сегодня?",
	["¡Hola, %s! Noche de luna: perfecta para la manada."] = "Привет, %s! Лунная ночь — то, что нужно стае.",
	["¡Hola, %s! Tú y yo vamos a cuidar a nuestro alfa."] = "Привет, %s! Мы с тобой будем беречь нашего альфу.",
	["¡Hoy Alfa cumple %d años! La Jauría lo hizo con cariño para ti. ¿Lo festejamos con una salchicha?"] = "Сегодня у Alfa день рождения, лет: %d! La Jauría сделала его с любовью для тебя. Отпразднуем сосиской?",
	["¡Hoy Alfa cumple 1 año! La Jauría lo hizo con cariño para ti. ¿Lo festejamos con una salchicha?"] = "Сегодня Alfa исполняется 1 год! La Jauría сделала его с любовью для тебя. Отпразднуем сосиской?",
	["¡Hoy cumplimos %d años cazando juntos, %s! Gracias por dejarme ser tu loba. Auuuu."] = "Сегодня %d г. с тех пор, как мы охотимся вместе, %s! Спасибо, что позволил мне быть твоей волчицей. Ау-у-у.",
	["¡Hoy cumplimos 1 año cazando juntos, %s! Gracias por dejarme ser tu loba. Auuuu."] = "Сегодня ровно год, как мы охотимся вместе, %s! Спасибо, что позволил мне быть твоей волчицей. Ау-у-у.",
	["¡Hoy empezamos juntos!"] = "Сегодня мы начали вместе!",
	["¡La Lya de %s me contestó el saludo! Ya somos manada."] = "Лия игрока %s ответила на приветствие! Теперь мы стая.",
	["¡La Lya de %s me saludó! Entre lobas nos entendemos."] = "Лия игрока %s поздоровалась со мной! Мы, волчицы, друг друга понимаем.",
	["¡Le encantan! Pero las mías son más ricas."] = "Обожает их! Но мои вкуснее.",
	["¡Lista para entregar!"] = "Готово к сдаче!",
	["¡Lista! Sigue: %s"] = "Готово! Дальше: %s",
	["¡Listo para seguir de caza!"] = "Готов снова на охоту!",
	["¡Listo! %s precios guardados."] = "Готово! Сохранено цен: %s.",
	["¡Listo! Alfa ya es tuyo"] = "Готово! Alfa теперь твой",
	["¡Listo! Tu escritorio de Alfa queda así. Para volver a una pantalla: /alfa pantallas volver."] = "Готово! Рабочий стол Alfa остаётся таким. Вернуть один экран: /alfa pantallas volver.",
	["¡Llegando al andén!"] = "Подъезжаем к платформе!",
	["¡Llegó el Festival de Invierno! En Forjaz y Orgrimmar el árbol se llena de luces y regalos."] = "Пришел Зимний Покров! В Стальгорне и Оргриммаре елка полна огней и подарков.",
	["¡Lo lograste: %s! Esa salchicha de premio me la voy a comer despacito."] = "Ты справился: %s! Эту сосиску-награду я съем не спеша.",
	["¡Lo tienes! %s ×%d"] = "Есть! %s ×%d",
	["¡Logro de la semana: %s!"] = "Достижение недели: %s!",
	["¡Logro de la semana: %s! %s"] = "Достижение недели: %s! %s",
	["¡Lok'tar, %s!"] = "Лок'тар, %s!",
	["¡Martillo de cólera!"] = "Молот гнева!",
	["¡Meta de pesca del día cumplida! %s. Te ganaste una salchicha."] = "Цель рыбалки на сегодня выполнена! %s. Ты заслужил сосиску.",
	["¡Mi primera salchicha contigo! Esta no la voy a olvidar nunca."] = "Моя первая сосиска с тобой! Эту я никогда не забуду.",
	["¡Mira cómo brilla! Ese no lo saca cualquiera."] = "Смотри, как блестит! Такую не всякий поймает.",
	["¡Misión completada: %s!"] = "Задание выполнено: %s!",
	["¡Mmm, qué rica! Gracias, eres el mejor lobo de la manada."] = "Ммм, вкуснятина! Спасибо, ты лучший волк в стае.",
	["¡Modo aprendiz! La primera vez que salga cada aviso, te cuento de dónde viene y cómo apagarlo."] = "Режим ученика! Когда оповещение появится впервые, я расскажу, откуда оно и как его отключить.",
	["¡Mordedura de mangosta!"] = "Укус мангуста!",
	["¡Nivel %d!"] = "Уровень %d!",
	["¡Nivel %d! Date un momento para presumirlo, te lo ganaste."] = "Уровень %d! Найди минутку похвастаться — есть чем!",
	["¡Nivel %d! Paso firme y colmillo afilado."] = "Уровень %d! Твердый шаг и острые клыки.",
	["¡Nivel %d! Tu esfuerzo se nota. Sigue así."] = "Уровень %d! Твои старания видны. Так держать.",
	["¡Nivel %d! ¡Auuu! Así se sube en manada."] = "Уровень %d! Ауууу! Вот так растет стая.",
	["¡Nivel %d, bien hecho! Revisa si tu entrenador tiene algo nuevo."] = "Уровень %d, отлично! Загляни, нет ли у учителя чего-то нового.",
	["¡Nivel %d, y el anterior hace nada! Aúllo dos veces, una por cada uno. ¡Auuuu, auuuu!"] = "Уровень %d, а предыдущий был только что! Повою дважды, по разу за каждый. Ауууу, ауууу!",
	["¡Nivel 10! Ya tienes talentos: elígelos con calma, Talentos te ayuda."] = "Уровень 10! Теперь у тебя есть таланты: выбирай спокойно, «Таланты» помогут.",
	["¡Nivel 20! Ya puedes con mazmorras de verdad. ¿Armamos grupo?"] = "Уровень 20! Теперь тебе по силам настоящие подземелья. Соберем группу?",
	["¡Nivel 30! Ya vas a la mitad del camino. ¡Qué orgullo de manada!"] = "Уровень 30! Полпути позади. Стая гордится тобой!",
	["¡Nivel 40! Ya puedes aprender a montar. ¡Tu primera montura te espera!"] = "Уровень 40! Теперь можно научиться верховой езде. Твой первый транспорт ждет!",
	["¡Nivel 50! Ya se huele la cima. Junta oro para lo que viene."] = "Уровень 50! Вершина уже чувствуется. Копи золото на то, что впереди.",
	["¡Nivel 60!"] = "Уровень 60!",
	["¡Nivel 60! ¡Lo lograste, alfa! Ahora toca cazar en grande."] = "Уровень 60! У тебя получилось, альфа! Теперь время большой охоты.",
	["¡Nueva página en tu historia: %s! %s"] = "Новая страница в твоей истории: %s! %s",
	["¡Nuevo récord!"] = "Новый рекорд!",
	["¡Nuevo récord: %d misiones en un día! Ni la manada te alcanza."] = "Новый рекорд: %d заданий за день! Даже стая не поспевает.",
	["¡Nuevo récord: %s! (antes %s)"] = "Новый рекорд: %s! (был %s)",
	["¡Ojo! Tu precio está %d %% por debajo de lo que vale."] = "Осторожно! Твоя цена на %d %% ниже стоимости.",
	["¡Otro nivel tan pronto! Nivel %d. ¡Auuuu, esta racha no la para nadie!"] = "Еще один уровень так скоро! Уровень %d. Ауууу, эту серию никому не остановить!",
	["¡Perdiste su atención!"] = "Ты потерял его внимание!",
	["¡Pez de la semana cumplido!"] = "Рыба недели поймана!",
	["¡Plan cumplido!"] = "План выполнен!",
	["¡Plan cumplido! Te queda %d misión en tu registro: Alfa arma la ruta para cerrarla."] = "План выполнен! В журнале осталось заданий: %d. Alfa построит маршрут, чтобы их закрыть.",
	["¡Plan cumplido! Te quedan %d misiones en tu registro: Alfa arma la ruta para cerrarlas."] = "План выполнен! В журнале осталось заданий: %d. Alfa построит маршрут, чтобы их закрыть.",
	["¡Plan terminado!"] = "План выполнен!",
	["¡Por la Alianza, %s!"] = "За Альянс, %s!",
	["¡Primera vez aquí!"] = "Впервые здесь!",
	["¡Primera vez! Nuevo en tu diario"] = "Впервые! Новая запись в журнале",
	["¡Qué buena racha traes! Sigue así."] = "Какая удачная серия! Так держать.",
	["¡Qué bueno tenerte de vuelta, %s! Aquí sigo, cuidándote la espalda."] = "Как хорошо, что ты снова здесь, %s! Я все еще рядом и прикрываю тебе спину.",
	["¡Qué bueno verte!"] = "Рада тебя видеть!",
	["¡Qué gusto verte de vuelta! Esto es lo que trae esta versión para ti y tu manada."] = "Рады снова тебя видеть! Вот что эта версия принесла тебе и твоей стае.",
	["¡Qué gusto verte, %s! La manada ya te esperaba."] = "Рада тебя видеть, %s! Стая уже ждала тебя.",
	["¡Repara tu equipo!"] = "Почините экипировку!",
	["¡Reto cumplido: %s! Me gané una salchicha... digo, te la ganaste tú. Bueno, nos la ganamos."] = "Испытание выполнено: %s! Я заработала сосиску... то есть ты ее заработал. Ладно, мы заработали.",
	["¡Revancha!"] = "Реванш!",
	["¡Récord en esta zona!"] = "Рекорд в этой зоне!",
	["¡Récord! Antes: %s"] = "Рекорд! Раньше: %s",
	["¡Sal de ahí!"] = "Уходи оттуда!",
	["¡Salchicha! *mueve la cola a toda velocidad* Gracias, gracias."] = "Сосиска! *виляет хвостом изо всех сил* Спасибо, спасибо.",
	["¡Salimos de %s! %s adentro."] = "Мы вышли из %s! %s внутри.",
	["¡Salimos de la mazmorra! %s adentro."] = "Мы вышли из подземелья! %s внутри.",
	["¡Se vendieron %d de tus subastas!"] = "Продано %d из твоих лотов!",
	["¡Se vendió %d de tus subastas!"] = "Продан %d из твоих лотов!",
	["¡Sesenta! Lo lograste. Me debes una salchicha gigante."] = "Шестьдесят! Получилось. С тебя гигантская сосиска.",
	["¡Subiste a nivel %d! Cada nivel te hace más fuerte."] = "Новый уровень — %d! Каждый уровень делает тебя сильнее.",
	["¡Sí! Estira la ventana del juego sobre tus dos monitores y abre «Dos pantallas»: dejo el juego en el principal y pongo en el otro tu guía, la flecha grande, el mapa, el medidor, tus bolsas y lo que te digo. Con un solo monitor, también va a un lado."] = "Да! Растяните окно игры на два монитора и откройте «Два экрана»: я оставлю игру на основном, а на другой поставлю гайд, большую стрелку, карту, счётчик, сумки и мои подсказки. С одним монитором — сбоку.",
	["¡Sí, acompáñame!"] = "Да, будь рядом!",
	["¡Te está atacando a ti!"] = "Он атакует тебя!",
	["¡Te extrañé, %s! Corrí hasta aquí para verte."] = "Я скучала по тебе, %s! Бежала со всех лап, чтобы тебя увидеть.",
	["¡Te extrañé, %s! Tu ruta sigue donde la dejaste."] = "Я скучала, %s! Твой маршрут там же, где и был.",
	["¡Terminaste %s!"] = "Готово: %s!",
	["¡Terminaste esta guía!"] = "Ты прошёл этот гайд!",
	["¡Terminaste esta guía! Elige la siguiente y sigue subiendo con la manada."] = "Этот гайд пройден! Выбери следующий и продолжай расти вместе со стаей.",
	["¡Terminaste tu guía!"] = "Гайд пройден!",
	["¡Terminaste!"] = "Готово!",
	["¡Tienes todo!"] = "У тебя все есть!",
	["¡Tierra a la vista!"] = "Земля на горизонте!",
	["¡Tierra a la vista! La manada desembarca en %s"] = "Земля на горизонте! Стая высаживается: %s",
	["¡Tierra a la vista! Llegas en %s"] = "Земля на горизонте! Прибудешь через %s",
	["¡Tierra a la vista: %s!"] = "Земля на горизонте: %s!",
	["¡Todo listo para %s!"] = "Всё готово для %s!",
	["¡Todo listo para la mazmorra!"] = "Все готово к подземелью!",
	["¡Tu %s llegó a %d/%d! Ya puedes aprender el rango %s."] = "%s: %d/%d! Теперь можно выучить уровень «%s».",
	["¡Tu lista de compras está completa!"] = "Список покупок собран!",
	["¡Tu mejor pelea!"] = "Ваш лучший бой!",
	["¡Tú!"] = "Ты!",
	["¡Un año! Un año entero de caminos, misiones y salchichas. Te quiero mucho, compañero de caza."] = "Год! Целый год дорог, заданий и сосисок. Я тебя очень люблю, напарник по охоте.",
	["¡Un ejemplar! Más grande que casi todos"] = "Настоящий экземпляр! Крупнее почти всех",
	["¡Un mes cazando juntos! Gracias por dejarme acompañarte. ¿Me das una salchicha de festejo?"] = "Месяц охоты вместе! Спасибо, что берёшь меня с собой. Праздничную сосиску?",
	["¡Va! Te lo sigo diciendo, con gusto."] = "Хорошо! Продолжу говорить, с радостью.",
	["¡Van %d misiones hoy! La manada está orgullosa."] = "Заданий сегодня: %d! Стая гордится.",
	["¡Vencieron a %s al intento %d!"] = "%s повержен с %d-й попытки!",
	["¡Volviste, %s! Estira las patas y vámonos."] = "С возвращением, %s! Разомни лапы — и в путь.",
	["¡Voy!"] = "Иду!",
	["¡Vuelta completa!"] = "Обход завершен!",
	["¡Ya amaneció, lobo! Buenos días. El sol pinta bonito Azeroth."] = "Рассвело, волк! Доброе утро. Солнце красиво освещает Азерот.",
	["¡Ya casi llegas!"] = "Почти на месте!",
	["¡Ya eres nivel %d! La manada aúlla por ti."] = "Уже уровень %d! Стая воет в твою честь.",
	["¡Ya estamos en %s! Deja que el tanque jale primero y quédate cerca de quien cura."] = "Мы в %s! Пусть танк пуллит первым, а ты держись рядом с лекарем.",
	["¡Ya estamos en la mazmorra! Deja que el tanque jale primero y quédate cerca de quien cura."] = "Мы в подземелье! Пусть танк пуллит первым, а ты держись рядом с лекарем.",
	["¡Ya estás en la %s!"] = "Ты в: %s!",
	["¡Ya estás en otro plano!"] = "Ты уже в другом слое!",
	["¡Ya la desbloqueaste!"] = "Ты её разблокировал!",
	["¡Ya llegaste al 60!"] = "Ты достиг 60-го!",
	["¡Ya llegaste, %s! Te extrañé. ¿A dónde vamos hoy?"] = "Наконец-то ты здесь, %s! Я скучала. Куда отправимся сегодня?",
	["¡Ya llegó! Vamos, manada"] = "Прибыли! Вперёд, стая",
	["¡Ya se ve la torre! Bajas en %s"] = "Башня уже видна! Сходишь через %s",
	["¡Ya terminaste %d misiones! Vamos a cobrar la recompensa."] = "Выполнено заданий: %d! Пойдем за наградой.",
	["¡Ya!"] = "Пора!",
	["¡Yo te la guardé! En Historias está todo lo que cuentan tus misiones, para leerlo cuando quieras."] = "А я её сохранила! В «Историях» всё, что рассказывают твои задания, читай когда хочешь.",
	["¡con eso subes de nivel!"] = "с этим ты получишь уровень!",
	["¡Ñam! Con esta van %d. Eres mi persona favorita de todo Azeroth."] = "Ням! С этой уже %d. Ты мой самый любимый человек во всем Азероте.",
	["«%s»"] = "«%s»",
	["«%s» no es algo de Combate. Prueba: %s."] = "«%s» — такого нет в «Бою». Попробуй: %s.",
	["«%s» tiene su historia. ¿Te la cuento?"] = "У «%s» есть своя история. Рассказать?",
	["«%s» ya está en verde: solo da puntos a veces y gastas materiales de más."] = "«%s» стал зелёным: очки дают лишь иногда, а материалы уходят зря.",
	["«%s» ya quedó. Su final vale la pena, ¿te lo cuento?"] = "«%s» позади. Ее концовка того стоит — рассказать?",
	["«%s» · nivel %d"] = "«%s» · уровень %d",
	["«%s»: %s."] = "«%s»: %s.",
	["«%s»: hay que llevar el recado y hablar con quien te espera."] = "«%s»: нужно отнести весточку и поговорить с тем, кто ждет.",
	["«%s»: toca %s."] = "«%s»: пора %s.",
	["«%s»: ¿la sigues tú también?"] = "«%s»: пойдёшь по нему тоже?",
	["«%s»… hace %s de eso. ¡Qué buena caza fue esa!"] = "«%s»… это было %s назад. Какая была охота!",
	["«Ahora no» o «No volver a mostrar»."] = "«Не сейчас» или «Больше не показывать».",
	["«Alejar más la cámara» de Comodidades está encendido y manda sobre este valor al entrar."] = "Включено «Отдалять камеру сильнее» из «Удобств», и при входе оно перекрывает это значение.",
	["«Alfa: llévame» en tu registro de misiones"] = "«Alfa: веди туда» в журнале заданий",
	["«Antes de entrar»"] = "«Перед входом»",
	["«Aprender todo» en el entrenador"] = "«Изучить всё» у учителя",
	["«Avisarme cuando se conecte»"] = "«Сообщить, когда зайдет»",
	["«Buscar cerca» en la página Hoy"] = "«Найти рядом» на странице «Сегодня»",
	["«Buscar cerca» te lleva con flecha a lo que necesitas, y «Mis planes» arma tus propias metas, que se marcan solas."] = "«Найти рядом» ведет тебя стрелкой к нужному, а «Мои планы» составляют твои собственные цели, которые отмечаются сами.",
	["«Camino al 60» en Hoy"] = "«Путь к 60» в «Сегодня»",
	["«Cerrar mis misiones» desde Hoy"] = "«Закрыть мои задания» из «Сегодня»",
	["«Cerrar mis misiones» está al día"] = "«Закрыть мои задания»: все актуально",
	["«Comprar lo que falta»"] = "«Купить недостающее»",
	["«Comprar lo que falta» en las guías de oficio"] = "«Купить недостающее» в гайдах профессий",
	["«Copiar el nombre» en el clic derecho"] = "«Копировать имя» по правому клику",
	["«Enviar ya por el navegador»"] = "«Отправить через браузер»",
	["«Igual que Alfa» sigue el estilo de Ajustes > Apariencia y cambia con él."] = "«Как в Alfa» следует стилю из Настройки > Внешний вид и меняется вместе с ним.",
	["«Invitar al clan» en el clic derecho"] = "«Пригласить в гильдию или сообщество» по правому клику",
	["«Llegaste», «Usa tu piedra de hogar» y los viajes salen aquí."] = "«Ты на месте», «Используй камень возвращения» и поездки появляются здесь.",
	["«Llegaste», «Usa tu piedra de hogar» y los viajes salen donde está la flecha. Apágalo para ponerlas en otro lugar."] = "«Ты на месте», «Используй камень возвращения» и поездки появляются у стрелки. Выключи, чтобы поставить их в другое место.",
	["«Llévame a…» (página Ruta, tu tecla o /alfa llevame): eliges el lugar y te llevo con vuelos, barcos, zepelines y portales, tramo por tramo."] = "«Отведи меня в…» (страница «Маршрут», твоя клавиша или /alfa llevame): выбери место, и я поведу с полетами, кораблями, дирижаблями и порталами, отрезок за отрезком.",
	["«Llévame» a un mineral o una hierba"] = "«Отведи меня» к руде или траве",
	["«Llévame» pone la flecha en este paso; «Siguiente» lo da por hecho y te lleva al que sigue."] = "«Отведи меня» направит стрелку на этот шаг; «Дальше» отметит его и перейдет к следующему.",
	["«Llévame» te lleva a la zona más cercana de tu nivel."] = "«Отведи меня» ведёт в ближайшую зону вашего уровня.",
	["«Ponte esto» con el equipo mejor"] = "«Надень это» для лучшего снаряжения",
	["«Ponte esto», lista de compras, oficios del 1 al 300 y subastar fácil."] = "«Надень это», список покупок, профессии с 1 до 300 и простой аукцион.",
	["«Prepárame» recoge solo las que ya puedes tomar y te lleva a la entrada."] = "«Подготовь меня» берет только те, что уже можно взять, и ведет ко входу.",
	["«Reportar» ya los lleva."] = "«Отчет» их уже включает.",
	["«Saltar a mi nivel»"] = "«К моему уровню»",
	["«Seguir» en La Jauría ya no se suelta cuando tu guía cambia de paso ni cuando vas por tu cuerpo: al terminar, la flecha vuelve con quien sigues."] = "«Следовать» в La Jauría больше не сбрасывается, когда гид переходит к другому шагу или ты бежишь к своему телу: потом стрелка снова указывает на того, за кем ты следуешь.",
	["«Separar»: lo épico con candado a la subasta"] = "«Разобрать»: эпические под замком на аукцион",
	["«Siempre» sirve si un amigo encantador te ayuda. Las tablas de desencantar son estimadas."] = "«Всегда» подходит, если вам помогает друг-чародей. Таблицы распыления примерные.",
	["«Tomar todo» en el buzón"] = "«Забрать все» у почтового ящика",
	["«Tomar todo» en el buzón, tu oro por hora y aviso de bolsas casi llenas."] = "«Забрать все» у почтового ящика, твое золото в час и предупреждение о почти полных сумках.",
	["«Tu sesión» en Hoy: tu tiempo, tu XP por hora y el oro que ganaste, siempre al día."] = "«Твоя сессия» в «Сегодня»: время, опыт в час и заработанное золото, всегда актуально.",
	["«Ver el siguiente» te deja mirar el paso que viene y lo dice claro; y un solo contador de pasos hechos."] = "«Показать следующий» позволяет посмотреть следующий шаг и ясно об этом говорит; а счетчик выполненных шагов теперь один.",
	["«[Misión] está lista para entregar» y «¡Misión completada!» en el chat del grupo, para todos. Apagado, solo te salen a ti."] = "«[Задание] можно сдать» и «Задание выполнено!» в чате группы, для всех. Выключено — видишь только ты.",
	["«[Misión] está lista para entregar» y «¡Misión completada!». En grupo lo ve todo el grupo; solo, sale en tu chat."] = "«[Задание] можно сдать» и «Задание выполнено!». В группе это видят все; в одиночку — в твоём чате.",
